def transition(state, action):
    """
    Apply an action to the state and return the resulting state.
    The state is expected to be an iterable of Entity objects.
    """
    next_state = deepcopy(state)
    agents = get_entities_by_name(next_state, "Agent")
    if not agents:
        return next_state
    agent = agents[0]
    if action == "turn left":
        dx, dy = agent.direction
        agent.direction = (dy, -dx)
    elif action == "turn right":
        dx, dy = agent.direction
        agent.direction = (-dy, dx)
    elif action == "move forward":
        dx, dy = agent.direction
        new_x, new_y = agent.x + dx, agent.y + dy
        if not get_entities_by_position(
            next_state, new_x, new_y
        ) or all(
            entity.name != "Wall"
            for entity in get_entities_by_position(next_state, new_x, new_y)
        ):
            agent.x, agent.y = new_x, new_y
    # Other actions, including "toggle", leave the state unchanged.
    return next_state

def transition(state, action):
    """Apply an action and return a new state."""
    next_state = deepcopy(state)
    agents = get_entities_by_name(next_state, "Agent")
    if not agents:
        return next_state
    agent = agents[0]
    if action == "turn left":
        dx, dy = agent.direction
        agent.direction = (dy, -dx)
        return next_state
    if action == "turn right":
        dx, dy = agent.direction
        agent.direction = (-dy, dx)
        return next_state
    if action == "move forward":
        new_x, new_y = _front_position(agent)
        blockers = get_entities_by_position(next_state, new_x, new_y)
        blocked = False
        for entity in blockers:
            name = getattr(entity, "name", entity.__class__.__name__)
            if name in ("Wall", "Box", "Lava"):
                blocked = True
            elif name == "Door" and not _door_is_open(entity):
                blocked = True
        if not blocked:
            agent.x, agent.y = new_x, new_y
        return next_state
    if action == "pick up":
        x, y = _front_position(agent)
        keys = [
            entity for entity in get_entities_by_position(next_state, x, y)
            if getattr(entity, "name", entity.__class__.__name__) == "Key"
        ]
        if keys and getattr(agent, "carrying", None) is None:
            key = keys[0]
            agent.carrying = key
            next_state.remove(key)
        return next_state
    if action == "drop":
        carried = getattr(agent, "carrying", None)
        if carried is not None:
            x, y = _front_position(agent)
            if not get_entities_by_position(next_state, x, y):
                # Preserve the carried object's properties when possible.
                if isinstance(carried, Entity):
                    carried.x, carried.y = x, y
                    next_state.append(carried)
                agent.carrying = None
        return next_state
    if action == "toggle":
        x, y = _front_position(agent)
        doors = [
            entity for entity in get_entities_by_position(next_state, x, y)
            if getattr(entity, "name", entity.__class__.__name__) == "Door"
        ]
        if not doors:
            return next_state
        door = doors[0]
        door_state = str(getattr(door, "state", "")).lower()
        if _door_is_open(door):
            door.state = "closed"
            if hasattr(door, "is_open"):
                door.is_open = False
            if hasattr(door, "open"):
                door.open = False
            return next_state
        locked = door_state == "locked" or bool(getattr(door, "is_locked", False))
        if locked:
            carried = getattr(agent, "carrying", None)
            if _key_color(carried) == getattr(door, "color", None):
                door.state = "open"
                if hasattr(door, "is_locked"):
                    door.is_locked = False
                if hasattr(door, "is_open"):
                    door.is_open = True
                if hasattr(door, "open"):
                    door.open = True
        else:
            door.state = "open"
            if hasattr(door, "is_open"):
                door.is_open = True
            if hasattr(door, "open"):
                door.open = True
        return next_state
    # "nothing" and any unrecognized action leave the state unchanged.
    return next_state

def transition(state, action):
    """
    Args:
        state: A collection of entities in the environment.
        action: The action to execute.
    Returns:
        A new collection of entities representing the next state.
    """
    # Copy the entities so the input state is not modified.
    next_state = [
        type(entity)(entity.x, entity.y, **{
            key: value
            for key, value in entity.__dict__.items()
            if key not in ("name", "x", "y")
        })
        for entity in state
    ]
    agents = get_entities_by_name(next_state, "Agent")
    if not agents:
        return next_state
    agent = agents[0]
    if action in ("turn left", "turn right"):
        dx, dy = agent.direction
        if action == "turn left":
            # Rotate counterclockwise in the coordinate convention shown.
            agent.direction = (dy, -dx)
        else:
            agent.direction = (-dy, dx)
    elif action == "move forward":
        dx, dy = agent.direction
        target_x, target_y = agent.x + dx, agent.y + dy
        # Move only if the destination is not occupied by a wall.
        if not get_entities_by_position(
            next_state, target_x, target_y
        ) or all(
            entity.name != "Wall"
            for entity in get_entities_by_position(next_state, target_x, target_y)
        ):
            agent.x, agent.y = target_x, target_y
    # "toggle" has no effect in the demonstrated experiences.
    return next_state

